#include <stdlib.h>
#include <sys/resource.h>

PixelChannels **acquire_pixel_channels(const Image *images) {
    rlimit limit;
    getrlimit(RLIMIT_NPROC, &limit);
    long thread_count = limit.rlim_cur;

    long columns = 0;
    while (images[columns].data != NULL) {
        columns++;
    }

    PixelChannels **channels = (PixelChannels **)malloc(thread_count * sizeof(PixelChannels *));
    if (!channels) {
        return NULL;
    }

    for (long i = 0; i < thread_count; i++) {
        channels[i] = (PixelChannels *)malloc(columns * sizeof(PixelChannels));
        if (!channels[i]) {
            for (long j = 0; j < i; j++) {
                free(channels[j]);
            }
            free(channels);
            return NULL;
        }
    }

    return channels;
}

PixelChannels **allocate_pixel_channels(const Image *images) {
