    long thread_limit = sysconf(_SC_THREAD_THREADS_MAX);
    if (thread_limit == -1) {
        return NULL;
    }

    // Initialize variables for number of columns and threads
    size_t num_columns = 0;
    size_t num_threads = 0;

    // Determine the total number of columns across all images and number of threads to use
    while (images[num_columns].width != 0 && images[num_columns].height != 0) {
        num_columns++;
    }

    num_threads = (thread_limit > num_columns) ? num_columns : thread_limit;

    // Allocate memory for the two-dimensional array of pixel channels
    PixelChannels **pixel_channels = (PixelChannels **)malloc(num_columns * sizeof(PixelChannels *));
    if (pixel_channels == NULL) {
        return NULL;
    }

    for (size_t i = 0; i < num_columns; i++) {
        pixel_channels[i] = (PixelChannels *)malloc(num_threads * sizeof(PixelChannels));
        if (pixel_channels[i] == NULL) {
            // Free previously allocated memory in case of failure
            for (size_t j = 0; j < i; j++) {
                free(pixel_channels[j]);
            }
            free(pixel_channels);
            return NULL;
        }
    }

    // Initialize pixel channels for each image and thread
    for (size_t i = 0; i < num_columns; i++) {
        for (size_t j = 0; j < num_threads; j++) {
            pixel_channels[i][j].width = images[i].width;
            pixel_channels[i][j].height = images[i].height;
            pixel_channels[i][j].data = NULL;
            // Initialize other relevant members of PixelChannels structure if needed
        }
    }

    return pixel_channels;
}

#include <stdlib.h>
