PixelChannels **allocate_pixel_channels(const Image *images) {
    // Get the resource limit for threads
    int max_threads = sysconf(_SC_THREAD_THREADS);

    // Initialize number of columns and threads
    int num_columns = images[0].width * images[0].height;
    int num_threads = (max_threads > 0) ? max_threads : 4;

    // Allocate memory for the array of pixel channels
    PixelChannels **pixel_channels = (PixelChannels **)malloc(num_threads * sizeof(PixelChannels *));
    if (!pixel_channels) {
        return NULL; // Memory allocation failed
    }

    // Allocate memory for each row (thread-specific pixel channels)
    for (int i = 0; i < num_threads; ++i) {
        pixel_channels[i] = (PixelChannels *)malloc(num_columns * sizeof(PixelChannels));
        if (!pixel_channels[i]) {
            // Free previously allocated memory in case of failure
            for (int j = 0; j < i; ++j) {
                free(pixel_channels[j]);
            }
            free(pixel_channels);
            return NULL;
        }
    }

